// --- inputs -----------------------------------------------------------------
let email_intent = ZT.getVariableValue("email_intent", "");
let requester_type = ZT.getVariableValue("hc_requester_type", "driver");
let response_variant = ZT.getVariableValue("hc_response_variant", "");
let intents = [];
if (email_intent !== "") {
  intents = email_intent.split(", ");
}

// --- transform: the key the generation AI Action drafts against -------------------
// intent (+ response variant) + audience. Only approved driver copy exists today, so a
// fleet run is flagged for the agent on the dashboard. OPEN ITEM #3.
let base = intents.length === 1 ? intents[0] : "multiple";
let hc_template_key = base;
if (response_variant !== "") {
  hc_template_key = hc_template_key + ":" + response_variant;
}
hc_template_key = hc_template_key + ":" + requester_type;
let hc_copy_approved = requester_type === "driver";

// Some approved templates carry a gap only the agent can fill. Each row names the native
// field on screen 23 that asks for it, the driver that shows that field, and the token node
// 26 replaces with the answer, so the draft arrives on the dashboard already filled in.
// A new placeholder is one row here plus one conditional field on screen 23.
const emailInputsByVariant = {
  underpayment_response: [
    { field: "hc_unit_rate", driver: "hc_ask_unit_rate", token: "[INSERT UNIT RATE EXCLUDING VAT]" }
  ]
};
const allDrivers = ["hc_ask_unit_rate"];
let hc_email_inputs = emailInputsByVariant[response_variant] || [];
let askedDrivers = [];
for (let i = 0; i < hc_email_inputs.length; i++) {
  askedDrivers.push(hc_email_inputs[i].driver);
}

// --- outputs ----------------------------------------------------------------
// Salesforce Case Origin stamped on every AI-handled case.
ZT.setFormData("sf_Origin", "Zingtree AI");
ZT.setFormData("hc_template_key", hc_template_key);
ZT.setFormData("hc_copy_approved", hc_copy_approved);
// Screen 23's conditional fields test these drivers as the strings "true" / "false".
for (let i = 0; i < allDrivers.length; i++) {
  ZT.setFormData(allDrivers[i], askedDrivers.indexOf(allDrivers[i]) !== -1 ? "true" : "false");
}
ZT.setFormData("hc_email_inputs", JSON.stringify(hc_email_inputs));
ZT.setFormData("hc_email_inputs_required", hc_email_inputs.length > 0);

26.content:
// --- inputs -----------------------------------------------------------------
let intentResult = actions.automate_hc_email_intent_prod;
let sfCase = actions.get_case_details__prod.records[0];
let email_response = actions.automate_hc_email_generation_prod.email || "";
let email_intent = ZT.getVariableValue("email_intent", "");
let sf_CaseNumber = ZT.getVariableValue("sf_CaseNumber", "");
let selected_topic = ZT.getVariableValue("sf_Topic__c", "");
let selected_subtopic = ZT.getVariableValue("sf_Sub_Topic__c", "");
let ai_exception_reason = ZT.getVariableValue("ai_exception_reason", "");
let agent_added_request = ZT.getVariableValue("agent_added_request", "");
let requester_type = ZT.getVariableValue("hc_requester_type", "driver");
let response_variant = ZT.getVariableValue("hc_response_variant", "");
let copy_approved = ZT.getVariableValue("hc_copy_approved", true);
let email_inputs = JSON.parse(ZT.getVariableValue("hc_email_inputs", "[]"));

// --- shared helpers -----------------------------------------------------------
const escapeHtml = value => String(value == null ? "" : value)
  .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
  .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
// Case.Description is the inbound email as PLAIN TEXT (confirmed on live CO 10 responses,
// 2026-09-29): escape it and keep its line breaks before it goes into any HTML block.
const emailBodyHtml = value => escapeHtml(value).replace(/\r?\n/g, "<br>");
const muted = cls => `<span class="${cls}">&mdash;</span>`;
const formatValue = value => {
  if (value == null || value === "") return muted("case-review-muted");
  if (value === true || value === false) return value ? "Yes" : "No";
  if (value instanceof Array) return value.length ? escapeHtml(value.join(", ")) : muted("case-review-muted");
  if (value instanceof Object) return escapeHtml(JSON.stringify(value));
  return escapeHtml(value);
};
const normalizeIntentKey = value => String(value || "").trim().toLowerCase().replace(/\s+/g, "_");

// --- the details the agent gave on screen 23, written into the draft ------------------
// Each token is matched case-insensitively with flexible spacing, in case the generation
// AI Action reflows it. A gap still open afterwards (the AI reworded the token, or a new
// template gained one nobody mapped) sends the case to screen 33 through router 31.
for (let i = 0; i < email_inputs.length; i++) {
  let pattern = email_inputs[i].token.replace(/[.*+?^${}()|[\]\\]/g, "\\$&").replace(/\s+/g, "\\s+");
  let answer = escapeHtml(String(ZT.getVariableValue(email_inputs[i].field, "")).trim());
  email_response = email_response.replace(new RegExp(pattern, "gi"), function () { return answer; });
}
let unfilledGap = email_response.match(/\[\s*INSERT[^\]]*\]/i);
let manual_changes_reason = unfilledGap
  ? "The reply still contains " + unfilledGap[0] + " - fill it in before this goes out."
  : "";

// intent key -> Salesforce Topic / Sub Topic (also the dashboard label). The map is declared
// once, in node 19; this is that same map read back. Homecharge has its own Topic namespace:
// HC-Online / HC-Not Online. OPEN ITEM #6.
const salesforceByIntent = JSON.parse(ZT.getVariableValue("hc_salesforce_by_intent", "{}"));
const variantLabels = JSON.parse(ZT.getVariableValue("hc_variant_labels", "{}"));
const intentKeys = Object.keys(salesforceByIntent);
// Topic -> Sub Topic pairs the manual-changes form offers, taken from this same map so every
// pair the agent can pick is one Salesforce accepts (Corpay UK matrix, 2026-09-22). Topic
// options are the topics that have at least one live intent. No "Other" - it is not a valid
// Topic__c value. Screen 33's subtopic list is filtered by the chosen Topic in script_code.
let subtopicChoices = [];
let topicOptions = [];
for (let i = 0; i < intentKeys.length; i++) {
  let key = intentKeys[i];
  let row = salesforceByIntent[key];
  subtopicChoices.push(row);
  if (topicOptions.indexOf(row.topic) === -1) {
    topicOptions.push(row.topic);
  }
}
const requesterLabels = { driver: "Driver", fleet: "Fleet manager" };

// --- detected intents ---------------------------------------------------------
let rawIntents = [].concat(intentResult.email_intent || []);
let detectedIntents = rawIntents
  .map(item => normalizeIntentKey(item instanceof Object ? (item.intent || item.name || item.key || item.value || "") : item))
  .filter(Boolean);
let detectedLabels = [...new Set(detectedIntents.map(key => salesforceByIntent[key] ? salesforceByIntent[key].subtopic : key))];
let has_multiple_intents = detectedIntents.length > 1 ? "true" : "false";

// --- Salesforce Topic / Sub Topic ----------------------------------------------
// Topic always follows the Sub Topic it is paired with in the map.

// the detected intents as Topic / Sub Topic pairs, one per Sub Topic, for screen 32
let detectedChoices = [];
let seenSubtopics = [];
for (let i = 0; i < detectedIntents.length; i++) {
  let row = salesforceByIntent[detectedIntents[i]];
  if (row && seenSubtopics.indexOf(row.subtopic) === -1) {
    detectedChoices.push(row);
    seenSubtopics.push(row.subtopic);
  }
}
// Single intent: its own pair. Multiple intents: email_intent is a comma string that matches
// no key, so default to the FIRST detected pair - always a pair Salesforce accepts - rather
// than a fixed Topic with an empty Sub Topic. The agent confirms or changes it on screen 32.
let salesforce = salesforceByIntent[email_intent] || detectedChoices[0] || { topic: "HC-Online", subtopic: "" };

// screen 32's Topic list: the topics of the detected pairs (e.g. HC-Online and HC-Not Online
// for a Tariff + Password Reset email). script_code filters its Sub Topic list by Topic,
// exactly as it does on screen 33.
let detectedTopics = [];
for (let i = 0; i < detectedChoices.length; i++) {
  if (detectedTopics.indexOf(detectedChoices[i].topic) === -1) {
    detectedTopics.push(detectedChoices[i].topic);
  }
}

// --- dashboard ----------------------------------------------------------------
const renderRow = (label, value) => `
  <div class="case-review-row">
    <div class="case-review-row-label">${escapeHtml(label)}</div>
    <div class="case-review-row-value">${formatValue(value)}</div>
  </div>`;

const renderIntentPills = () => `
  <div class="case-review-intent-grid">
    ${intentKeys.map(key => {
      let isPresent = detectedIntents.includes(key);
      let theme = isPresent
        ? { cardBg: "#e8f5ec", border: "#d3eadb", valueColor: "#16803d", text: "Yes" }
        : { cardBg: "#fae9e9", border: "#f2d2d2", valueColor: "#c62525", text: "No" };
      return `
      <div class="case-review-intent-simple-card" style="background:${theme.cardBg};border-color:${theme.border};">
        <div class="case-review-intent-simple-title">${escapeHtml(salesforceByIntent[key].subtopic)}</div>
        <div class="case-review-intent-simple-value" style="color:${theme.valueColor};">${theme.text}</div>
      </div>`;
    }).join("")}
  </div>`;

// Only driver copy has been signed off by Corpay. A fleet run is re-framed by the
// generation AI Action and flagged here so the agent reads it before sending. OPEN ITEM #3.
const renderCopyNotice = () => copy_approved === true || copy_approved === "true" ? `` : `
  <div class="case-review-card" style="background:#fff7ed;border-color:#fed7aa;">
    <h3 class="case-review-card-title">Fleet wording - not yet signed off</h3>
    <p>The approved Homecharge templates are written for drivers. This reply was re-framed for a fleet manager, so read it in full before sending.</p>
  </div>`;

// A placeholder that survived screen 23's answers: router 31 sends the case to the
// manual-changes screen. Say so here - the dashboard still shows a Send button.
const renderManualEditNotice = () => manual_changes_reason === "" ? `` : `
  <div class="case-review-card" style="background:#fef2f2;border-color:#fecaca;">
    <h3 class="case-review-card-title">This reply has to be edited before it is sent</h3>
    <p>${escapeHtml(manual_changes_reason)}</p>
  </div>`;

let case_review_html = `
<div class="case-review-shell">
  <div class="case-review-panel">
    <div class="case-review-hero">
      <div class="case-review-hero-top">
        <div class="case-review-hero-copy">
          <div class="case-review-eyebrow">Case Review &middot; Homecharge</div>
          <h2 class="case-review-main-title">Email Response Summary</h2>
          <div class="case-review-subtitle">Case <strong>${formatValue(sf_CaseNumber)}</strong>
            <span class="case-review-subtitle-separator">&middot;</span> ${formatValue(detectedLabels.join(", "))}</div>
        </div>
        <div class="case-review-hero-metrics-card">
          <div class="case-review-hero-metric">
            <div class="case-review-hero-metric-label">Confidence Score</div>
            <div class="case-review-hero-metric-value">${formatValue(intentResult.confidence_score)}</div>
          </div>
          <div class="case-review-hero-metric">
            <div class="case-review-hero-metric-label">Confidence Explanation</div>
            <div class="case-review-hero-metric-text">${formatValue(intentResult.confidence_score_extracts)}</div>
          </div>
        </div>
      </div>
    </div>
    <div class="case-review-body">
      <div class="case-review-grid">
        <div class="case-review-col case-review-col-left">
          <div class="case-review-card">
            <h3 class="case-review-card-title">Case Details</h3>
            ${renderRow("Case Number", sf_CaseNumber)}
            ${renderRow("Customer Request", detectedLabels.join(", "))}
            ${renderRow("Requester Email", sfCase.SuppliedEmail)}
            ${renderRow("Sent by", requesterLabels[requester_type])}
            ${agent_added_request ? renderRow("Added by agent", agent_added_request) : ""}
            ${response_variant ? renderRow("Response variant", variantLabels[response_variant]) : ""}
          </div>
          <div class="case-review-card">
            <h3 class="case-review-card-title">Subtopics found</h3>
            ${renderIntentPills()}
          </div>
        </div>
        <div class="case-review-col case-review-col-right">
          ${renderManualEditNotice()}
          ${renderCopyNotice()}
          <div class="case-review-card">
            <h3 class="case-review-card-title">Original Customer Email</h3>
            <div class="case-review-html-card-body">${sfCase.Description && String(sfCase.Description).trim() !== "" ? emailBodyHtml(sfCase.Description) : muted("case-review-muted")}</div>
          </div>
          <div class="case-review-card case-review-response-card">
            <h3 class="case-review-card-title">Email Response</h3>
            <div class="case-review-html-card-body">${email_response.trim() !== "" ? email_response : muted("case-review-muted")}</div>
          </div>
        </div>
      </div>
    </div>
  </div>
</div>`.trim();

// --- part of the request not recognised (screen 62) ----------------------------------
// On an in-scope case ai_exception_reason is empty unless the intent AI Action mapped some
// requests and could not map another; it then names the part it did not recognise. The agent
// reviews the draft on screen 62 and types what is missing; the reply is then regenerated with
// agent_added_request in the generation AI Action's context, and this node runs again.
let unrecognised_review_needed = ai_exception_reason !== "" && agent_added_request === "";
let unrecognised_review_html = `
<div class="case-review-card" style="background:#fffbeb;border-color:#fde68a;">
  <h3 class="case-review-card-title">Part of this request was not recognised</h3>
  <p>Not all elements of this customer request have been matched to a recognised intent. Please review the draft response and add any missing information before generating the final email.</p>
  <p><strong>Recognised:</strong> ${escapeHtml(detectedLabels.join(", "))}</p>
  <p><strong>Not recognised:</strong> ${escapeHtml(ai_exception_reason)}</p>
</div>
${case_review_html}`;

// --- manual-changes form (Topic + Subtopic + editable HTML body) -----------------
const buildOptions = (options, selectedValue, placeholder) =>
  `<option value="">${escapeHtml(placeholder)}</option>` + options.map(option =>
    `<option value="${escapeHtml(option)}"${option === selectedValue ? ' selected="selected"' : ""}>${escapeHtml(option)}</option>`).join("");
// Every Sub Topic option carries the Topic it belongs to; script_code reads data-topic to
// filter the Sub Topic list by the chosen Topic on screens 32 and 33.
const buildSubtopicOptions = (choices, selectedValue) =>
  `<option value="" data-topic="">Select Subtopic</option>` + choices.map(choice =>
    `<option value="${escapeHtml(choice.subtopic)}" data-topic="${escapeHtml(choice.topic)}"${choice.subtopic === selectedValue ? ' selected="selected"' : ""}>${escapeHtml(choice.subtopic)}</option>`).join("");

let request_form_html = `
<div class="zt-form-card">
  <div class="zt-form-header">
    <h2 class="zt-form-title">Original Customer Email</h2>
    <div class="zt-form-subtitle case-review-html-card-body">${sfCase.Description && String(sfCase.Description).trim() !== "" ? emailBodyHtml(sfCase.Description) : "&mdash;"}</div>
  </div>
  <div class="zt-form-header">
    <h2 class="zt-form-title">Request Details</h2>
    <p class="zt-form-subtitle">Complete the fields below.</p>
  </div>
  <div class="zt-form-grid">
    <div class="zt-form-field">
      <label for="sf_Topic__c" class="zt-form-label">Topic <span class="zt-required">*</span></label>
      <select id="sf_Topic__c" name="sf_Topic__c" data-name="sf_Topic__c" class="zt-data zt-form-control" required>
        ${buildOptions(topicOptions, selected_topic || salesforce.topic, "Select Topic")}
      </select>
    </div>
    <div class="zt-form-field">
      <label for="sf_Sub_Topic__c" class="zt-form-label">Subtopic <span class="zt-required">*</span></label>
      <select id="sf_Sub_Topic__c" name="sf_Sub_Topic__c" data-name="sf_Sub_Topic__c" class="zt-data zt-form-control" required>
        ${buildSubtopicOptions(subtopicChoices, selected_subtopic || salesforce.subtopic)}
      </select>
    </div>
  </div>
  <div class="zt-form-field zt-form-field-full">
    <label class="zt-form-label">HTML Body</label>
    <div id="htmlBodyEditor" class="zt-rich-editor" contenteditable="true">${email_response || "<p>Start typing...</p>"}</div>
    <textarea id="HtmlBody" name="HtmlBody" data-name="HtmlBody" class="zt-data" style="display:none;">${escapeHtml(email_response)}</textarea>
    <div class="zt-form-help">Format text visually (bold, line breaks, etc.)</div>
  </div>
</div>`.trim();

// --- multiple-subtopics form (agent picks the one Salesforce Sub Topic) ---------
let multiple_subtopics_form_html = `
