// --- inputs -----------------------------------------------------------------
let send = actions.send_email_simple_prod;
let responseCode = send._zt_meta.response.code;
let callSucceeded = responseCode >= 200 && responseCode < 300;
let sf_Topic__c = ZT.getVariableValue("sf_Topic__c", "");
let sf_Sub_Topic__c = ZT.getVariableValue("sf_Sub_Topic__c", "");

let html_body = ZT.getVariableValue("HtmlBody", "");

// --- grade the send -----------------------------------------------------------
// Two ways this fails: a non-2xx from Salesforce, or a 2xx whose composite result says
// isSuccess false. Only a 2xx carries a result to read; a non-2xx carries the raw body.
let emailSent = false;
let errorEmailMessage = "Salesforce returned status " + responseCode + ". " + send._zt_meta.response.body;
if (callSucceeded) {
  let result = send.value[0];
  emailSent = result.isSuccess === true;
  errorEmailMessage = "";
  if (!emailSent) {
    errorEmailMessage = result.errors[0].message;
  }
}

// --- summary screen ---------------------------------------------------------
const escapeHtml = value => String(value == null ? "" : value)
  .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
  .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
const renderRow = (label, value) => `
  <div class="email-summary-row">
    <div class="email-summary-row-label">${escapeHtml(label)}</div>
    <div class="email-summary-row-value">${value ? escapeHtml(value) : '<span class="email-summary-muted">&mdash;</span>'}</div>
  </div>`;

let email_sent_summary_html = `
<div class="email-summary-card-shell">
  <div class="email-summary-header">
    <div class="email-summary-icon">&#10003;</div>
    <div class="email-summary-header-copy">
      <h2 class="email-summary-title">Email Sent Successfully</h2>
      <p class="email-summary-subtitle">Great, the email was sent and the Salesforce fields below were updated.</p>
    </div>
  </div>
  <div class="email-summary-card">
    <h3 class="email-summary-card-title">Updated Salesforce Fields</h3>
    ${renderRow("Topic", sf_Topic__c)}
    ${renderRow("Sub Topic", sf_Sub_Topic__c)}
  </div>
  <div class="email-summary-card">
    <h3 class="email-summary-card-title">Email Sent</h3>
    <div class="email-summary-html-body">${html_body.trim() !== "" ? html_body : '<span class="email-summary-muted">&mdash;</span>'}</div>
  </div>
</div>`.trim();

// --- outputs ----------------------------------------------------------------
ZT.setFormData("emailSent", emailSent ? "true" : "false");
ZT.setFormData("errorEmailMessage", errorEmailMessage);
// Display HTML is form data so the screen still renders when a session is reopened after the
// 1-hour transforms TTL. Form-data merges render newlines as <br>, so it is written on one line.
ZT.setFormData("email_sent_summary_html", email_sent_summary_html.replace(/\s*\n\s*/g, " "));

