let caseFetch = actions.get_case_details__prod;
let code = caseFetch._zt_meta.response.code;
// Graded on the status code, then on the records the Salesforce Connected Object returns.
// A launch with no case (bare preview, bad Id) still reaches screen 4.
let caseRead = code >= 200 && code < 300 && Array.isArray(caseFetch.records) && caseFetch.records.length > 0;

// --- outputs ----------------------------------------------------------------
// Written before any account or eligibility check, so the form data report carries the
// queue on every case, including one with no linked account (Corpay UK, 28 Sep standup).
// Node 8 routes on this value; screen 11 prints it.
let last_owner_queue_name = caseRead ? (caseFetch.records[0].Last_Owner_Queue_Name__c || "") : "";
